$path='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\zh-CN\story\chapter2s1.ks'
$m=@{
199='「……十……一十！」[p]';201='柔和的温度与带着淡淡甜香的风拂过脸颊，朦胧中的意识感知到了现实。[p]';203='「――壹十。喂，壹十！」[p]';205='远处传来呼唤我名字的声音。[p]';206='那是略带无奈、却又温柔关心着我，呼唤我名字的美丽声音。[p]';207='――不，也算不上温柔。少女用相当强硬的语气继续说道。[p]';209='「壹十，有客人！有人叫你点单！」[p]';211='（……糟、糟了！）[p]';214='在瞳的呼唤下，我猛然回过神来。[p]';215='眼前是熟悉的咖啡店“异常”的柱子和桌子。[p]';217='以及双手不停挥舞、抬头看着我的青梅竹马幻影。[p]';218='看到她焦急的表情，我才想起自己正在打工。[p]';219='看来是明亮阳光、舒适的湿度与温度让我放松，不知不觉打了个盹。[p]';222='（谢了，帮大忙！）[p]';223='「好的，请稍等！」[p]';226='我从木制圆凳上起身，抽出夹在口袋里的记事本，走向客人的座位。[p]';227='不管客人再少，打工时睡觉算什么事？[p]';228='一边接单，我一边斥责自己没用。[p]';229='然而，催促反省的理性之外，内心依旧有些心不在焉。[p]';232='总觉得做了一个很长的梦。像是在过去与未来之间往返，夹杂惊叹与怀念的漫长记忆之旅。[p]';233='依稀记得的内容，是我还是毛头小子时的回忆。[p]';234='那时我还年轻。现在我也是个孩子，但过去的我更加幼稚。[p]';235='那是个卑劣又不讲义气的人，若能回到过去，我真想用十全的力量把他打飞。[p]';236='但是――只有那一刻，在那列电车里主动迈出身体，我想夸奖过去的自己。[p]';237='因为多亏如此，我才能再次和瞳成为朋友。[p]';238='那之后，我们最终翘掉了模拟考。[p]';239='我拼尽全力道歉，瞳说愿意原谅我，我们终于和好了。[p]';240='和好后的下一学年――初中三年级，我们的关系稍微改变了。[p]';241='我们再次一起上学。走廊擦肩而过时，她也会向我挥手。[p]';242='初中最后的社团比赛，她还来观众席为我加油过一次。[p]';243='不过她很害羞，躲在远离大家的树荫下加油。[p]';244='后来，瞳开始辅导我的学习。放学后的图书室里，我们一起学习的机会多了起来。[p]';247='那是一段幸福的日子。不知真相、愚蠢却珍贵的日子。[p]';250='「你说幸福……现在就不幸福了吗？」[p]';252='（不，现在也足够幸福。只是……）[p]';254='如果你还活着，我一定会幸福到无以复加――我忍不住这样想。[p]';257='幻影困惑地淡淡一笑。只有那温柔的笑容，自那天起仍如记忆般未曾改变。[p]';267='「壹十君，能过来一下吗？」[p]';269='过了一会儿，我忙着接单、端菜等大厅工作时，[p]';270='咖啡店店长、那位老绅士――老板叫住了我。[p]';272='「好的，什么事？」[p]';274='「现在该是休息时间了。其实我试做了店里准备推出的新蛋糕。」[p]';275='「蛋糕放在冰箱里，能和例君一起尝尝，告诉我感想吗？」[p]';277='「可以吗？谢谢您！」[p]';278='「那我去叫例前辈！」[p]';281='能把老板的新蛋糕当作员工餐吃，真是占尽便宜。[p]';282='之前吃过的蒙布朗也美味至极，我不禁满怀期待。[p]';283='我兴冲冲地脱下围裙，挂到衣架上。[p]';284='然后顺着脚步，走向正在咖啡滴滤器前待命的少女――例前辈。[p]';286='我打工的咖啡店“异常”由包括我在内的三名员工经营。[p]';287='也许还有其他兼职，但工作半年以来，我没见过第四名员工。[p]';288='第一位是刚才谈到蛋糕的老板。他是店主，主要负责厨房。[p]';289='第二位是我，负责大厅。接单、端菜、收拾残局等接待工作是我的职责。[p]';292='而第三名少女――[p]';295='――个子娇小，拥有如人偶般可爱的容貌。[p]';296='或许因为是咖啡店，她总是穿着女仆装，是店里的招牌娘――例前辈。[p]';299='「例前辈，休息时间到了。老板说一起尝尝试做的蛋糕。」[p]';301='「…………嗯。」[p]';304='例前辈轻轻点头，灵巧地用小手开始收拾桌子。[p]';305='例前辈负责咖啡。顾名思义，她的工作只有冲咖啡。[p]';306='她完全不接待客人。也许是外表太可爱，经常有客人搭话，但她基本什么也不说。[p]';307='她似乎会听，也会用手势回应，但表情始终固定得像无表情面具。[p]';308='所以接待工作全由我负责，料理当然由老板负责，只有收到咖啡订单时例前辈才会行动。[p]';309='我也怀疑这样的分工是否妥当，但既然老板认可，兼职的我没资格多嘴。[p]';310='而且，她在“异常”里也是立场相当特殊的员工。[p]';311='――不，准确地说，在这个人类社会里也是如此。[p]';314='「我收拾好了。壹十，走吧。」[p]';316='「好的，这就来。」[p]';318='我思考间她似乎已经收拾完毕，例前辈也脱下围裙转身离开。[p]';319='我跟在比我小一圈、不，足足小两圈以上的前辈身后，前往休息室。[p]';321='……真的，这样一看，她果然只像个初中生。[p]';322='然而，例前辈不只是工龄，连年龄也是我的前辈，[p]';323='她的特殊立场并不是因为她是初中生、双脚踏入法律灰色地带――[p]';324='不过，说她存在于法律灰色地带也不算错――[p]';325='毕竟，法律概念是否适用于例前辈都很可疑。[p]';328='简单来说，她不是人类。[p]';329='她住在店里工作，却不是老板的孩子。[p]';330='据说她从老板出生以前更久远的时代起――已经作为不会衰老的少女活了将近三百年。[p]';331='不是别称或俗称，也不太适合作为名称的个体名。[p]';332='脱离人的常理、与众不同的存在――“例外存在”。[p]';333='那就是例前辈的名字――也是她的真身。[p]';337='「呐，壹十，今晚有空吗？」[p]';339='「晚上吗？我没什么特别的安排。」[p]';341='「那就以学姐的名义命令你。晚饭也有员工餐……一起看之前约好的电影吧。」[p]';343='「不用命令，只要是例前辈的邀请，我随时都会十全地答应。」[p]';347='「……谢谢，我很期待。」[p]';350='她的嘴角随着圆圆的脸颊微微上扬了一瞬，随即恢复平时的无表情。[p]';351='但不知是不是错觉，例前辈的脚步似乎比刚才轻快了些。[p]';353='虽然从脸色和声调的平坦难以看出内心，但我觉得我们建立了良好的关系。[p]';354='她自称也被他人称作例外存在，但正常相处时只是个童颜可爱的前辈。[p]';355='老实说，我并不是真的相信例前辈有三百岁，[p]';356='但没有理由怀疑纯真的前辈，所以就当她三百岁吧。[p]';357='询问女性年龄是不礼貌的，至于面对活了三百年以上的存在是否也适用，就暂且不论。[p]';358='撇开年龄真假不谈，我从未怀疑例前辈本身不是普通人。[p]';361='因为她――例外存在之所以成为例外的理由，我也十全知晓。[p]';363='「……咦？」[p]';366='「嗯？怎么了，前辈？」[p]';368='例前辈打开冰箱门准备取出蛋糕，动作却停了下来。[p]';370='我从她身后越过头顶探看，发现她手里拿着一盘看起来美味的巧克力蛋糕。[p]';372='「只有一块蛋糕。」[p]';374='「啊，真的呢。」[p]';376='她说过要和我们一起吃，我还以为有两块，[p]';377='看来其实是想让我们两人分一块。[p]';380='「……我以为有两人份。」[p]';382='看来例前辈也有同样想法，声音里透出一丝悲伤。[p]';384='「怎么办？要不要用叉子切得均匀一点？」[p]';387='听到我的提议，例前辈用力摇头。[p]';389='「不用。就这样一人一口地吃。」[p]';392='「一人一块……可这里只有一块。」[p]';394='「嗯。所以――增加。」[p]';396='「……啊。」[p]';401='话音刚落，例前辈毫不犹豫地施展了属于例外的力量。[p]';402='啪的一声，眼睑为滋润干涩的眼睛闭合又张开――在那[ruby text="しゅゆ"]短暂的眨眼间，眼前发生了不可能发生的事。[p]';407='她用纤细的肩膀轻轻撞上门关好冰箱，转身将右手伸向我。[p]';408='伸出的右手，以及贴在胸前的左手。[p]';409='两只手上的盘子里，各放着一块本应世上仅有一块的试做蛋糕――两块。[p]';412='「……例前辈，老板说过吧？除非有特别理由，否则不能使用复制的力量。」[p]';414='「这就是特别理由。只准备一块，是爷爷的错。」[p]';416='「这、这样也行吗……？」[p]';418='她毫不在意地把复制出来的蛋糕盘递给我。[p]';419='接下它，我就会成为违反老板吩咐的共犯，[p]';422='既然已经增加了，丢掉太浪费，我只好放弃抵抗，一起承担罪责。[p]';423='我们在休息室坐下，用准备好的叉子吃蛋糕。[p]';425='「……蛋糕很好吃呢。」[p]';428='「嗯，很好吃。」[p]';430='不愧是老板做的，蛋糕当然美味得十全十美。[p]';431='例前辈也张开小嘴，大口大口吃着同样的蛋糕。[p]';437='同样的蛋糕――毫厘不差、十全一致的同一件物品。[p]';439='我知道它不是吞进肚子便会消失的幻影或仿制品。[p]';440='质量守恒和熵都不相关，无论是什么――[p]';441='――即使是生命，也能以完全相同的状态复制出来。[p]';442='这似乎就是她作为例外所拥有的权能之一――[p]';444='从第一次亲眼见到时，我就放弃理解了。[p]';445='原理和机制，连我这个笨蛋都不可能想明白――[p]';446='更不用说，是否存在所谓过程都很可疑。[p]';447='例外存在。不知姓氏和名字的界限，推测年龄超过三百岁的不老少女。[p]';448='姓名与年龄都没有确证，但这份异常性却是毋庸置疑的真相。[p]';449='但是――[p]';453='「壹十，咖啡冲好了。」[p]';455='「谢谢。」[p]';457='「好好喝哦。我可是？倾注了真心的。」[p]';459='「为什么要用疑问语气……？」[p]';461='我接过温热的杯子，喝了一口饭后的咖啡。[p]';462='淡淡的苦味与甜蛋糕的余味绝妙交融，让舌头感到愉悦。[p]';464='「很好喝，例前辈。」[p]';468='「这样啊，太好了。」[p]';470='说着，她的嘴角又短暂地放松了一下。[p]';471='从铁面具缝隙中偶尔流露的情感色彩，让我对这位年长前辈产生近似保护欲的怜爱。[p]';474='――不论她是普通初中生，还是三百岁的不老例外少女，[p]';475='对我而言，她都是打工处可爱的前辈。[p]';476='而且，例前辈冲的咖啡是世界第一好喝。所以客人询问推荐时，我总会推荐咖啡。[p]';477='要在这家咖啡店工作，只要知道这一点就十全了。[p]';505='「也不算突然吧？你看，今天不是刚拿到升学志愿表吗？」[p]';507='「啊……这么说来，我确实拿到过那张纸。」[p]';515='「没有想去的高中吗？」[p]';517='「想去的高中吗……如果不考虑我的成绩，倒是有一所候选。」[p]';519='「哦？是哪所学校？」[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content $path -Encoding UTF8)
foreach($n in $m.Keys){$lines[$n-1]=$m[$n]}
[IO.File]::WriteAllLines($path,$lines,[Text.UTF8Encoding]::new($false))
